#!/bin/sh
# Generate packages/core/schema/agent-spec.schema.json and apps/web/src/gen/agent-spec.ts
# from the Pydantic models in ovas-core. `scripts/gen.sh check` fails if they are stale.
set -eu
cd "$(dirname "$0")/.."
SCHEMA=packages/core/schema/agent-spec.schema.json
TS=apps/web/src/gen/agent-spec.ts
OUT=$(mktemp -d)
uv run --quiet python -m ovas_core.schema_export "$OUT/schema.json"
mkdir -p "$(dirname "$TS")"
pnpm exec json2ts -i "$OUT/schema.json" -o "$OUT/agent-spec.ts" --additionalProperties false \
  --bannerComment "// GENERATED by scripts/gen.sh from packages/core (ovas_core.spec). Do not edit."
pnpm exec prettier --config .prettierrc.json --log-level warn --write "$OUT/agent-spec.ts"
if [ "${1:-}" = check ]; then
  if ! cmp -s "$OUT/schema.json" "$SCHEMA" || ! cmp -s "$OUT/agent-spec.ts" "$TS"; then
    echo "Generated schema/types are out of date. Run: make gen" >&2
    exit 1
  fi
  echo "gen-check: up to date"
else
  cp "$OUT/schema.json" "$SCHEMA"
  cp "$OUT/agent-spec.ts" "$TS"
  echo "wrote $SCHEMA and $TS"
fi
rm -rf "$OUT"
